# First, let me load and examine all the demo pairs available

import os, glob, re, json, copy

def load_all_grids():
    """Load all grids (input/output pairs) from the session JSONL"""
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = os.path.join(d, '..', 'sessions', os.path.basename(d) + '.jsonl')

    grids = {}
    try:
        with open(session_file, 'r') as f:
            for line in f:
                entry = json.loads(line)
                if 'input' in entry and 'output' in entry:
                    task_id = entry.get('task_id', '')
                    grids[task_id] = grids.get(task_id, [])
                    grids[task_id].append((entry['input'], entry['output']))
    except FileNotFoundError:
        pass

    return grids

grids = load_all_grids()
print(f"Found {len(grids)} task(s) with demo pairs:")
for tid in grids:
    print(f"  {tid}: {len(grids[tid])} pairs")

# Check if our task has any demos
task_id = "task-fe7273b7"
if task_id in grids:
    print(f"\nTask {task_id} demo pairs:")
    for i, (inp, out) in enumerate(grids[task_id]):
        print(f"  Pair {i+1}: input {len(inp)}x{len(inp[0])}, output {len(out)}x{len(out[0])}")
else:
    print(f"\nTask {task_id} has NO demo pairs yet")

